#include "color_helper.hpp"
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("usage SHADERS MASK PARAMS NEWOUT");std::filesystem::path out=argv[4];auto read=[](const char* name,size_t n){std::ifstream f(name,std::ios::binary|std::ios::ate);if(!f||size_t(f.tellg())!=n*4)throw std::runtime_error("input size");std::vector<float>x(n);f.seekg(0);f.read((char*)x.data(),n*4);for(float v:x)if(!std::isfinite(v)||v<0||v>1)throw std::runtime_error("input range");return x;};auto mask=read(argv[2],65*49*4),ink=read(argv[3],8);if(!std::filesystem::create_directory(out))throw std::runtime_error("existing out");{TextLab v(argv[1]);std::array<float,8> colors;std::copy(ink.begin(),ink.end(),colors.begin());auto result=v.draw(mask,{.1f,.2f,.3f,.5f},colors);save(out/"color.rgba32f",result[0]);save(out/"velocity.rgba32f",result[1]);save(out/"id.rgba32f",result[2]);std::cout<<"validation_enabled="<<v.validation<<"\n";}if(validationErrors)throw std::runtime_error("validation");return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
